/* Skills-only infinite streams. Reuse the existing skill data, without editing it. */
(()=>{
 const section=document.querySelector('#competences'),panel=section.querySelector('#stack-panel'),reduce=matchMedia('(prefers-reduced-motion:reduce)'),fine=matchMedia('(hover:hover) and (pointer:fine)');
 const categories=[...panel.querySelectorAll('.rabat-skill-card')].map(card=>({title:card.querySelector('h3').textContent,items:[...card.querySelectorAll('.tech')].map(b=>({name:b.querySelector('strong').textContent,role:b.querySelector('small').textContent,detail:b.dataset.detail}))}));
 const subtitles=['Interfaces & expériences utilisateur','APIs · logique métier · applications serveur','Données · requêtes · modélisation','Versioning · collaboration · méthodes','Systèmes · environnement de développement','Langages · fondamentaux · interfaces de données'];
 const times=[24,32,27,30,25,34];
 const icons={React:['orbit-react','#61dafb'],JavaScript:['orbit-javascript','#f7df1e'],HTML5:['skill-html5','#e34f26'],CSS3:['skill-css3','#54a6df'],Python:['orbit-python','#79a7d2'],Django:['orbit-django','#8bc5a5'],'Java / JEE':['skill-java','#ef9b61'],'C# / .NET':['skill-csharp','#b082e8'],'PHP / Laravel':['skill-php','#a5a9e1'],'Node.js':['orbit-nodejs','#83cd29'],MySQL:['skill-mysql','#61a4c5'],SQL:['database','#8db8d0'],SGBD:['database','#a7bacd'],Git:['skill-git','#f05032'],Agile:['agile','#e9b66d'],Linux:['skill-linux','#f1cb6f'],C:['skill-c','#91b6e1'],'C++':['skill-cplusplus','#6ba6de'],'Django REST':['orbit-django','#9bcbb1']};
 const db='<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.6"><ellipse cx="16" cy="7" rx="11" ry="4.5"/><path d="M5 7v18c0 6 22 6 22 0V7M5 16c0 6 22 6 22 0"/></svg>',agile='<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M25 12A10 10 0 0 0 7 9M7 9V3M7 9h6M7 20a10 10 0 0 0 18 3m0 0v6m0-6h-6"/><path d="m12 16 3 3 6-7"/></svg>';
 function pill(item,duplicate=false){const [icon,color]=icons[item.name],b=document.createElement('button');b.className='tech stream-tech';b.type='button';b.dataset.detail=item.detail;b.dataset.skill=item.name;b.style.setProperty('--brand',color);if(duplicate){b.tabIndex=-1;b.dataset.duplicate='true'}else b.dataset.original='true';const symbol=document.createElement('span');symbol.className='tech-symbol stream-logo';symbol.setAttribute('aria-hidden','true');if(icon==='database'||icon==='agile')symbol.innerHTML=icon==='database'?db:agile;else{const img=document.createElement('img');img.src=`images/${icon}.svg`;img.alt='';img.width=36;img.height=36;img.decoding='async';symbol.append(img);if(item.name==='PHP / Laravel'||item.name==='C# / .NET'){const second=document.createElement('img');second.src=`images/skill-${item.name==='PHP / Laravel'?'laravel':'dotnetcore'}.svg`;second.alt='';second.width=21;second.height=21;symbol.append(second)}}const text=document.createElement('span');text.className='stream-tech-copy';const name=document.createElement('strong');name.textContent=item.name;const role=document.createElement('small');role.textContent=item.role;text.append(name,role);const label=document.createElement('span');label.className='stream-extra';label.textContent=item.detail;label.setAttribute('aria-hidden','true');b.append(symbol,text,label);return b}
 panel.classList.add('infinite-tech-stack');panel.replaceChildren();
 const bands=categories.map((category,i)=>{const band=document.createElement('article');band.className=`tech-stream-band ${i%2?'stream-reverse':''}`;band.style.setProperty('--stream-duration',`${times[i]}s`);band.style.setProperty('--entrance-delay',`${Math.min(i,3)*75}ms`);const header=document.createElement('header');header.className='tech-stream-heading';header.innerHTML=`<span class="stream-number">0${i+1}</span><div><h3>${category.title}</h3><p>${subtitles[i]}</p></div><span class="stream-flow" aria-hidden="true">${i%2?'←':'→'}<i></i></span>`;const viewport=document.createElement('div');viewport.className='tech-stream-viewport';const track=document.createElement('div');track.className='tech-stream-track';viewport.append(track);band.append(header,viewport);panel.append(band);return {band,viewport,track,category}});
 function fill(entry){const {viewport,track,category}=entry;if(track.contains(document.activeElement))return;const group=document.createElement('div');group.className='tech-stream-group';category.items.forEach(item=>group.append(pill(item)));track.replaceChildren(group);const base=group.getBoundingClientRect().width;const repeats=Math.max(1,Math.ceil((viewport.clientWidth+240)/Math.max(base,1)));for(let n=1;n<repeats;n++)category.items.forEach(item=>group.append(pill(item,true)));const clone=group.cloneNode(true);clone.setAttribute('aria-hidden','true');clone.querySelectorAll('button').forEach(b=>{b.tabIndex=-1;delete b.dataset.original;b.dataset.duplicate='true'});track.append(clone);if(entry.depth)entry.depth.disconnect();if(!reduce.matches){entry.depth=new IntersectionObserver(entries=>entries.forEach(e=>e.target.style.setProperty('--stage-scale',(0.96+e.intersectionRatio*.04).toFixed(3))),{root:viewport,threshold:[0,.25,.5,.75,1]});track.querySelectorAll('.stream-tech').forEach(b=>entry.depth.observe(b))}}
 bands.forEach(fill);let lastWidth=panel.clientWidth,resizeFrame=0;new ResizeObserver(()=>{if(Math.abs(lastWidth-panel.clientWidth)<15)return;lastWidth=panel.clientWidth;cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>bands.forEach(fill))}).observe(panel);
 const enter=new IntersectionObserver(entries=>entries.forEach(e=>{e.target.classList.toggle('stream-in-view',e.isIntersecting);if(e.isIntersecting)e.target.classList.add('stream-entered')}),{rootMargin:'50px',threshold:.02});bands.forEach(({band})=>enter.observe(band));
 function hidden(){section.classList.toggle('streams-suspended',document.hidden)}document.addEventListener('visibilitychange',hidden);hidden();
 bands.forEach(({band})=>{band.addEventListener('focusin',e=>{if(e.target.matches('[data-original]'))band.classList.add('stream-keyboard')});band.addEventListener('focusout',e=>{if(!band.contains(e.relatedTarget))band.classList.remove('stream-keyboard')})});
 let pointerFrame=0,last=null;function paint(){pointerFrame=0;if(!last||reduce.matches)return;const r=section.getBoundingClientRect();section.style.setProperty('--skills-x',`${last.clientX-r.left}px`);section.style.setProperty('--skills-y',`${last.clientY-r.top}px`);const target=last.target.closest('.stream-tech');if(target){const b=target.getBoundingClientRect();target.style.setProperty('--pill-rx',`${-((last.clientY-b.top)/b.height-.5)*5}deg`);target.style.setProperty('--pill-ry',`${((last.clientX-b.left)/b.width-.5)*6}deg`)}}if(fine.matches){section.addEventListener('pointermove',e=>{last=e;if(!pointerFrame)pointerFrame=requestAnimationFrame(paint)},{passive:true});section.addEventListener('pointerout',e=>{const b=e.target.closest('.stream-tech');if(b&&!b.contains(e.relatedTarget)){b.style.removeProperty('--pill-rx');b.style.removeProperty('--pill-ry')}});section.addEventListener('pointerleave',()=>{section.style.removeProperty('--skills-x');section.style.removeProperty('--skills-y')})}
})();
